const trigger = $node["GitHub pull request trigger"].json.body ?? $node["GitHub pull request trigger"].json;
if (!['opened', 'ready_for_review'].includes(trigger.action) || !trigger.pull_request) {
  return [];
}
const files = $input.all().map((item) => item.json.filename).filter(Boolean);
const modules = [...new Set(files.map((path) => path.split('/').slice(0, -1).join('/') || '(repository root)'))];
const issueReference = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s+#\d+/i.test(trigger.pull_request.body || '');
const checklist = [
  '## Automation review checklist',
  '',
  '**Summary:** ' + trigger.pull_request.title,
  '**Affected modules:** ' + (modules.length ? modules.map((module) => '`' + module + '`').join(', ') : 'No changed-file metadata returned.'),
  '',
  '- [ ] Tests cover the changed behavior or explain why they are not applicable.',
  '- [ ] README, API, model, benchmark, or deployment documentation is updated when the change changes those contracts.',
  '- [' + (issueReference ? 'x' : ' ') + '] Linked issue reference present.',
  '',
  'This comment is a reviewer reminder. It does not approve, merge, or alter the pull request.'
].join('\n');
return [{ json: { pr_number: trigger.pull_request.number, body: checklist } }];
